css:
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:32px}body{margin:0;background:#f4f0e6;color:#3f3a32;font:300 16px/1.5 Roboto,Arial,sans-serif}a{color:#002147;text-decoration:none}a:hover{text-decoration:underline}a:focus-visible,summary:focus-visible{outline:2px solid #002147;outline-offset:5px}.page{max-width:1140px;margin:auto;padding:96px 15px 48px;display:grid;grid-template-columns:350px minmax(0,730px);gap:30px}.identity{font-size:27.2px;line-height:40.8px;margin:0 0 32px;color:#333;font-weight:300}.identity strong{font-weight:700}.portrait{width:235px;height:253px;object-fit:cover;border-radius:4px;box-shadow:0 8px 18px #302b2429;display:block}.contacts{margin-top:60px;display:flex;flex-direction:column;align-items:flex-start;font-size:18px;line-height:26px}.contacts a{display:flex;gap:10px;align-items:center}.contacts svg{width:17px;height:17px;fill:currentColor}.top-nav{display:flex;justify-content:flex-end;gap:28px;margin:6px 0 44px;font-size:16px;font-weight:500}.top-nav a{color:#002147;font-weight:600;text-decoration:none}.top-nav a:hover{color:#000f24;text-decoration:underline;text-underline-offset:5px;text-decoration-thickness:2px}.top-nav a:focus-visible{outline:2px solid #002147;outline-offset:6px;border-radius:2px}p{margin:0 0 16px;text-align:justify}.section{margin-top:54px}.section h2{font:600 25px/1.35 Newsreader,Georgia,serif;color:#26241f;margin:0 0 22px;padding-bottom:12px;border-bottom:1px solid #dcd6ca}.entry{padding:5px 8px;margin:0 0 20px}.entry-title{font-weight:400;display:block;line-height:1.45}.authors{font-size:15px;margin-top:2px}.authors strong{font-weight:400}.venue{font-size:14px;font-weight:400}.paper-links{display:flex;gap:7px;margin-top:5px;font-size:12px}.paper-links a{border:1px solid #b5bec4;border-radius:3px;padding:0 7px}.meta{font-size:14px;color:#766e61}.entry p{margin:5px 0 0;text-align:left}.dated{display:flex;justify-content:space-between;gap:12px}.dated time{font-size:14px;white-space:nowrap;color:#766e61}details{margin:12px 8px}summary{cursor:pointer;color:#002147;font-size:14px}details .entry{margin-top:20px;padding-left:0}.teaching{padding-left:24px}.teaching li{margin-bottom:10px}.journey{display:flex;justify-content:space-between;gap:18px;text-align:center;margin-top:60px;padding-top:26px;border-top:1px solid #dcd6ca}.journey a{flex:1;font-size:13px}.journey b{display:block;font-size:16px;font-weight:500}.journey span{color:#766e61;font-size:12px}footer{text-align:right;margin-top:44px;font-size:12px;color:#766e61}.skip{position:absolute;left:15px;top:-60px;background:#f4f0e6;padding:8px}.skip:focus{top:15px}@media(min-width:1000px){.sidebar-inner{position:sticky;top:40px}}@media(max-width:1199px){.page{max-width:960px;grid-template-columns:290px minmax(0,610px)}}@media(max-width:991px){.page{max-width:760px;grid-template-columns:210px minmax(0,490px);gap:30px;padding-top:60px}.portrait{width:190px;height:205px}.identity{font-size:24px}.top-nav{gap:18px;font-size:14px}}@media(max-width:700px){.page{display:block;padding:32px 24px}.sidebar-inner{display:grid;grid-template-columns:130px 1fr;column-gap:24px}.identity{grid-column:1/-1;margin-bottom:20px;font-size:27.2px}.portrait{width:130px;height:145px}.contacts{margin:0;font-size:16px;align-self:center;line-height:28px}.top-nav{justify-content:flex-start;gap:20px;flex-wrap:wrap;margin:32px 0}.section{margin-top:38px}p{text-align:left}.dated{display:block}.journey{flex-wrap:wrap}.journey a{flex-basis:40%}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.journey a{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:14px}.journey img{width:125px;height:55px;object-fit:contain}.journey a:first-child img{width:44px}.journey a:nth-child(3) img{width:55px}@media(max-width:700px){.journey img{max-width:110px}}
.dated time{font-variant-numeric:tabular-nums;text-align:right;flex-shrink:0;min-width:155px}@media(max-width:700px){.dated time{display:block;text-align:left;min-width:0;margin-top:3px}}
.contact-row{display:flex;align-items:center;gap:6px;position:relative}.contacts .open-icon,.copy-button svg{fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;width:13px;height:13px}.contacts .open-icon{margin-left:3px;color:#766e61}.copy-button{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border:0;border-radius:4px;padding:5px;color:#766e61;background:transparent;cursor:pointer}.copy-button:hover{background:#e6e0d4;color:#002147}.copy-button:focus-visible{outline:2px solid #002147;outline-offset:2px}.copy-button[data-copied]{color:#286443}.copy-feedback{font-size:12px;color:#286443;white-space:nowrap;margin-left:3px}
